def _pool2():
    r = _rst()
    r.append(_row(2, i_mcyc=1, i_mstb=1, i_mwe=1, i_maddr=5, i_mdata=1, i_msel=0xF))
    r.append(_row(3, i_mcyc=1, i_mstb=1, i_mwe=1, i_maddr=6, i_mdata=2, i_msel=0xF))
    r.append(_row(4))
    r.append(_row(5))
