        ('hyp_limit_exhaustion', lambda: check_rows(_heads(), {'MAX_HYP': 1})['verdict'] == 'unresolved' and check_rows(_heads(), {'MAX_HYP': 1})['counts']['checked_scope']['suspended_rows'] > 0),
