        ('pool_limit_exhaustion', lambda: check_rows(_pool2(), {'MAX_CANCELED_POOL': 1})['verdict'] == 'unresolved'),
        ('invalid_limit_zero', lambda: check_rows(_write(), {'MAX_HYP': 0})['verdict'] == 'input_or_scope_invalid'),
